            ('user_quota:restore'::text, 'user_quota'::text, 'restore'::text, 'Restore user quota'::text),
            ('user_quota:update'::text, 'user_quota'::text, 'update'::text, 'Update user quota'::text)
      ) AS v(name, resource, action, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.permissions p WHERE p.name = v.name AND (p.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

    INSERT INTO public.roles (name, description)
    SELECT v.name, v.description
      FROM (VALUES
            ('super_admin'::text, NULL::text),
            ('admin'::text, NULL::text),
            ('user'::text, NULL::text),
            ('guest'::text, NULL::text)
      ) AS v(name, description)
     WHERE NOT EXISTS (SELECT 1 FROM public.roles r WHERE r.name = v.name AND (r.metadata->>'deleted_at') IS NULL)
    ON CONFLICT DO NOTHING;

    INSERT INTO public.role_permissions (role_id, permission_id)
    SELECT r.id, p.id
      FROM (VALUES
            ('super_admin'::text, '*:*'::text),
            ('admin'::text, 'bucket:*'::text),
            ('admin'::text, 'file:*'::text),
            ('admin'::text, 'quota:*'::text),
            ('admin'::text, 'share:*'::text),
            ('user'::text, 'bucket:create'::text),
            ('user'::text, 'bucket:read'::text),
            ('user'::text, 'comment:create'::text),
            ('user'::text, 'comment:delete'::text),
            ('user'::text, 'comment:read'::text),
            ('user'::text, 'comment:update'::text),
            ('user'::text, 'conversion:create'::text),
            ('user'::text, 'conversion:read'::text),
            ('user'::text, 'file:comment'::text),
            ('user'::text, 'file:convert'::text),
            ('user'::text, 'file:create'::text),
            ('user'::text, 'file:delete'::text),
            ('user'::text, 'file:download'::text),
            ('user'::text, 'file:lock'::text),
            ('user'::text, 'file:read'::text),
            ('user'::text, 'file:share'::text),
            ('user'::text, 'file:update'::text),
            ('user'::text, 'lock:create'::text),
            ('user'::text, 'lock:delete'::text),
            ('user'::text, 'lock:read'::text),
            ('user'::text, 'quota:read'::text),
            ('user'::text, 'share:create'::text),
            ('user'::text, 'share:read'::text),
            ('user'::text, 'share:revoke'::text),
            ('guest'::text, 'file:download'::text),
            ('guest'::text, 'file:read'::text)
      ) AS g(role, permission)
      JOIN public.roles r ON r.name = g.role AND (r.metadata->>'deleted_at') IS NULL
      JOIN public.permissions p ON p.name = g.permission AND (p.metadata->>'deleted_at') IS NULL
     WHERE NOT EXISTS (SELECT 1 FROM public.role_permissions rp WHERE rp.role_id = r.id AND rp.permission_id = p.id)
    ON CONFLICT DO NOTHING;

END $$;
